def _create_final_audit_verification_proof_verification_proof_verification_proof_verification_proof_witness(
    self,
) -> None:
    idempotency_key = self._audit_idempotency_key()
    if idempotency_key is None:
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    # 见证创建拒绝查询参数：参数校验先于体校验与认证结构。
    if parse_qsl(urlsplit(self.path).query, keep_blank_values=True):
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    # 正文恰含 proofSeq（非布尔正整数，任意长度）与 chainDigest
    # （64 位小写十六进制），键不得重复。
    raw_body = self._read_raw_body()
    fields = (
        None
        if raw_body is None
        else self._read_final_audit_verification_proof_verification_proof_verification_proof_verification_proof_witness_object(
            raw_body
        )
    )
    if fields is None:
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    # 仅接受单一 SLA-Auth：代理头、缺失、重复或结构非法均为非法请求。
    if self.headers.get_all(SLA_DELEGATION_HEADER):
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    auth = self._parse_sla_auth()
    if auth is None:
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    body_digest = hashlib.sha256(raw_body).hexdigest()
    status, payload = (
        self._apply_final_audit_verification_proof_verification_proof_verification_proof_verification_proof_witness(
            fields, auth, body_digest, idempotency_key
        )
    )
    self._json(status, payload)

def _read_final_audit_verification_proof_verification_proof_verification_proof_verification_proof_witness_object(
    self, body: bytes
) -> dict[str, Any] | None:
    parsed = self._read_json_object(body, unbounded_ints=True)
    if (
        parsed is None
        or set(parsed)
        != FINAL_AUDIT_VERIFICATION_PROOF_VERIFICATION_PROOF_VERIFICATION_PROOF_VERIFICATION_PROOF_WITNESS_FIELDS
    ):
        return None
    proof_seq = parsed["proofSeq"]
    chain_digest = parsed["chainDigest"]
    # 证明序号要求为非布尔正整数：零、负整数、布尔值与非整数为正文非法
    # （400/invalid_request）；超出存储范围但格式合法的正整数按链节点
    # 不存在处理（404/not_found）。
    if (
        not isinstance(proof_seq, int)
        or isinstance(proof_seq, bool)
        or proof_seq <= 0
    ):
        return None
    if (
        not isinstance(chain_digest, str)
        or DIGEST_PATTERN.fullmatch(chain_digest) is None
    ):
        return None
    return parsed

